// AnnualScore is the per-(subject, year) running roll-up. Years are
// calendar years (UTC) of the consumption hour_start. Stored in
// basis points (10000 = 100.00%).
type AnnualScore struct {
	SubjectId              string `protobuf:"bytes,1,opt,name=subject_id,json=subjectId,proto3" json:"subject_id,omitempty"`
	Year                   uint32 `protobuf:"varint,2,opt,name=year,proto3" json:"year,omitempty"`
	HoursWithData          uint64 `protobuf:"varint,3,opt,name=hours_with_data,json=hoursWithData,proto3" json:"hours_with_data,omitempty"`
	HoursFullyMatched      uint64 `protobuf:"varint,4,opt,name=hours_fully_matched,json=hoursFullyMatched,proto3" json:"hours_fully_matched,omitempty"`
	TotalWhConsumed        uint64 `protobuf:"varint,5,opt,name=total_wh_consumed,json=totalWhConsumed,proto3" json:"total_wh_consumed,omitempty"`
	TotalWhMatched         uint64 `protobuf:"varint,6,opt,name=total_wh_matched,json=totalWhMatched,proto3" json:"total_wh_matched,omitempty"`
	TotalWhMatchedSameZone uint64 `protobuf:"varint,7,opt,name=total_wh_matched_same_zone,json=totalWhMatchedSameZone,proto3" json:"total_wh_matched_same_zone,omitempty"`
	TotalWhMatchedStorage  uint64 `protobuf:"varint,8,opt,name=total_wh_matched_storage,json=totalWhMatchedStorage,proto3" json:"total_wh_matched_storage,omitempty"`
	// hourly_score = sum_h(min(matched_h, consumed_h)) / sum_h(consumed_h)
	// The numerator is tracked separately (sum_min_match_consumed)
	// because the per-hour cap can't be reconstructed from the global
	// totals once we cross hour boundaries.
	SumMinMatchConsumed uint64 `protobuf:"varint,9,opt,name=sum_min_match_consumed,json=sumMinMatchConsumed,proto3" json:"sum_min_match_consumed,omitempty"`
	LastUpdated         int64  `protobuf:"varint,10,opt,name=last_updated,json=lastUpdated,proto3" json:"last_updated,omitempty"`
}

